import{_ as a,a as r,b as t}from"./chunks/inspector.Cp7qKBuq.js";import{_ as i,o,c as n,al as l}from"./chunks/framework.7vp1BMOE.js";const b=JSON.parse('{"title":"Smartmicro Drone Altimeter (T132)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/dronecan/smartmicro_t132.md","filePath":"uk/dronecan/smartmicro_t132.md"}'),s={name:"uk/dronecan/smartmicro_t132.md"};function c(d,e,h,p,m,u){return o(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="smartmicro-drone-altimeter-t132" tabindex="-1">Smartmicro Drone Altimeter (T132) <a class="header-anchor" href="#smartmicro-drone-altimeter-t132" aria-label="Permalink to &quot;Smartmicro Drone Altimeter (T132)&quot;">​</a></h1><p>The Drone Altimeter by Smartmicro is radar based <a href="./../sensor/rangefinders">distance sensor</a> with a <a href="./">DroneCAN</a> interface.</p><p><img src="'+a+'" alt="T132"></p><ul><li>Altitude up to 175 m possible</li><li>Unbreakable, lightweight design (274 g, IP67)</li><li>For small drones in GNSS-denied environments</li><li>Plug-and-play integration with PX4 systems (DroneCAN compatible, 1 Mbit/s, 29-bit identifiers)</li><li>Automatic dual mode operation (medium/long range mode)</li><li>Highest accuracy, Altitude tracking</li><li>High electromagnetic susceptibility robustness: difficult to jam</li><li>Low observability (narrow beam, short dwell time)</li><li>Operates in 76-77 GHz band approved for altimeter operation in Europe</li><li>Made in Germany, specially designed for European drone manufactures</li><li>ITAR free, not dual-use classified</li><li>Mature hardware, in full production, available in high volume</li><li>Update rate of 55 ms</li></ul><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><p>Order this radar sensor from:</p><ul><li><a href="https://www.smartmicro.com/airborne/drone-altimeter/" target="_blank" rel="noreferrer">Smartmicro</a></li></ul><p>SmartMicro do not provide a cable that connects to Pixhawk-standard CAN bus connectors out of the box. You may however choose to purchase a &quot;Plug and Play&quot; cable, and replace its D-Sub-9 connector with the connector for your flight controller.</p><h2 id="характеристики-обладнання" tabindex="-1">Характеристики обладнання <a class="header-anchor" href="#характеристики-обладнання" aria-label="Permalink to &quot;Характеристики обладнання&quot;">​</a></h2><ul><li>Dimensions: 94.7 x 84.4 x 26.4 mm (plus connector)</li><li>Weight: 274 g</li><li>Connector: Hirose LF10 series</li><li>Operating Temperature: -40…+85°C</li><li>Shock/Vibration 100 g<sub>rms</sub>/14 g<sub>rms</sub></li><li>Voltage: DC 8 - 32 V.</li><li>Power: 3.75 to 5 W.</li></ul><h2 id="налаштування-програмного-забезпечення" tabindex="-1">Налаштування програмного забезпечення <a class="header-anchor" href="#налаштування-програмного-забезпечення" aria-label="Permalink to &quot;Налаштування програмного забезпечення&quot;">​</a></h2><h3 id="sensor-setup" tabindex="-1">Sensor Setup <a class="header-anchor" href="#sensor-setup" aria-label="Permalink to &quot;Sensor Setup&quot;">​</a></h3><p>For optimal performance, the antenna of the radar should be parallel to the surface of the earth during normal flight. The antenna is located directly behind the black plastic radome, so the black plastic surface should always be facing down.</p><p>The word &quot;TOP&quot; on the sensor label and the accompanying arrow should either point in the direction of flight or directly opposite the direction of flight. Please ensure, that the arrow never points perpendicular to the flight direction.</p><p>The sensor may be mounted behind flat plastics surfaces, e.g. inside the fuselage, if this surface is radar transparent.</p><h3 id="підключення" tabindex="-1">Підключення <a class="header-anchor" href="#підключення" aria-label="Permalink to &quot;Підключення&quot;">​</a></h3><p>The sensor connector is a 12-pin male bayonet type connector (waterproof IP67, series LF10WBRB-12PD, manufacturer Hirose, Japan).</p><p>To operate, connect CAN and GND with the controller.</p><p>Provide a DC voltage between 8 and 32 V. Power consumption is between 3.75 and 5 Watts.</p><p>The T132 has an internal CAN-Termination.</p><p><img src="'+r+'" alt="T132_wiring"></p><h3 id="налаштування-прошивки" tabindex="-1">Налаштування прошивки <a class="header-anchor" href="#налаштування-прошивки" aria-label="Permalink to &quot;Налаштування прошивки&quot;">​</a></h3><p>The sensor is shipped with the firmware. No setup is required. Future firmware update is possible with proprietary Smartmicro software via CAN bus.</p><h2 id="конфігурація-px4" tabindex="-1">Конфігурація PX4 <a class="header-anchor" href="#конфігурація-px4" aria-label="Permalink to &quot;Конфігурація PX4&quot;">​</a></h2><ul><li>In <em>QGroundControl</em> set the parameter <a href="./../advanced_config/parameter_reference#UAVCAN_ENABLE">UAVCAN_ENABLE</a> to <code>2</code> for dynamic node allocation.</li><li>Confirm that <a href="./../advanced_config/parameter_reference#UAVCAN_BITRATE">UAVCAN_BITRATE</a> is set to 1000000 (1 Mbit/s).</li><li>Enable <a href="./../advanced_config/parameter_reference#UAVCAN_SUB_RNG">UAVCAN_SUB_RNG</a>.</li><li>Set <a href="./../advanced_config/parameter_reference#EKF2_RNG_A_HMAX">EKF2_RNG_A_HMAX</a> to <code>175</code>.</li><li>Set <a href="./../advanced_config/parameter_reference#EKF2_RNG_QLTY_T">EKF2_RNG_QLTY_T</a> to <code>0.2</code>.</li><li>Set <a href="./../advanced_config/parameter_reference#UAVCAN_RNG_MIN">UAVCAN_RNG_MIN</a> to <code>1</code>.</li><li>Set <a href="./../advanced_config/parameter_reference#UAVCAN_RNG_MAX">UAVCAN_RNG_MAX</a> to <code>175</code>.</li><li>Reboot (see <a href="./../advanced_config/parameters">Finding/Updating Parameters</a>).</li><li>Connect Altimeter CAN to the Flight Controller CAN.</li></ul><p>See also <a href="./../dronecan/#distance-sensor-range-finder">Distance Sensor/Range Finder in <em>DroneCAN &gt; Subscriptions and Publications</em></a>.</p><p>Після активації модуль буде виявлено при завантаженні. Distance sensor data arrives at 18.2 Hz.</p><h2 id="sensor-operation" tabindex="-1">Sensor Operation <a class="header-anchor" href="#sensor-operation" aria-label="Permalink to &quot;Sensor Operation&quot;">​</a></h2><p>The measured altitude is perpendicular to the radome of the sensor. When the vehicle rolls or pitches, the measured altitude is too high and must be compensated by roll and pitch angles.</p><p>If the sensor is unable to determine the current altitude (too high, too low or occluded radome) this is signaled as (DroneCAN) <code>reading_type=undefined</code>.</p><p>The screenshot of the MAVLink Inspector shows a situation where the radome is intentionally occluded.</p><p><img src="'+t+'" alt="MAVLink Inspector"></p>',32)])])}const g=i(s,[["render",c]]);export{b as __pageData,g as default};
